<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Shield, Power, Globe2, SlidersHorizontal, Plus, ArrowDown, ArrowUp, Copy, Trash2, X, Minus, Check, Clipboard, LockKeyhole, Route, ChevronRight, Radio, LoaderCircle, RefreshCw, TriangleAlert } from 'lucide-vue-next'
import type { State, Prefs } from './api'
const window = globalThis.window
const state = ref<State>(), page = ref('home'), importing = ref(false), uri = ref(''), error = ref(''), pending = ref(false), interfaces = ref<string[]>([]), draft = ref<Prefs>(), now = ref(Date.now())
const selected = computed(() => state.value?.profiles.find(p => p.id === state.value?.selected))
const connection = computed(() => state.value?.connection)
const connected = computed(() => connection.value?.phase === 'connected')
const online = computed(() => connected.value && connection.value?.health === 'online')
const degraded = computed(() => connected.value && connection.value?.health === 'degraded')
const transitioning = computed(() => ['connecting', 'disconnecting'].includes(connection.value?.phase || ''))
const verifying = computed(() => connected.value && connection.value?.health === 'checking')
const idle = computed(() => connection.value?.phase === 'disconnected')
const label = computed(() => online.value ? 'Доступ через VPN подтверждён' : degraded.value ? 'Туннель запущен · нет ответа из интернета' : verifying.value ? 'Туннель запущен · проверяем доступ' : ({ disconnected: 'Готов к подключению', connecting: 'Подключение…', disconnecting: 'Отключение…' }[connection.value?.phase || 'disconnected']))
const heading = computed(() => online.value ? 'Вы подключены' : degraded.value ? 'Нет подтверждения доступа' : verifying.value ? 'Проверяем соединение' : transitioning.value ? (connection.value?.phase === 'connecting' ? 'Создаём соединение' : 'Завершаем соединение') : 'Подключитесь к свободе')
const statsAge = computed(() => connection.value?.statsAt ? Math.max(0, Math.floor((now.value - connection.value.statsAt) / 1000)) : 0)
const statsNote = computed(() => !connected.value ? 'Трафик через сервер' : connection.value?.statsStatus === 'pending' ? 'Ожидание счётчиков…' : connection.value?.statsStatus === 'stale' ? `Статистика задерживается${connection.value.statsAt ? ` · ${statsAge.value} с` : ''}. Последние значения сохранены.` : 'Трафик через сервер · обновление каждую секунду')
const elapsed = computed(() => { const s = Math.max(0, Math.floor((now.value - (connection.value?.since || now.value)) / 1000)); return [Math.floor(s / 3600), Math.floor(s / 60) % 60, s % 60].map(n => String(n).padStart(2, '0')).join(':') })
function bytes(n = 0) { return n < 1024 ? `${Math.round(n)} B` : n < 1048576 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB` }
function receive(value: State) { state.value = value }
async function run(fn: () => Promise<unknown>) { error.value = ''; pending.value = true; try { const result = await fn(); if (result && typeof result === 'object' && 'profiles' in result) receive(result as State) } catch (e) { error.value = (e as Error).message.replace(/^Error invoking remote method '[^']+': Error: /, '') } finally { pending.value = false } }
async function toggle() { await run(() => connected.value ? window.reality.disconnect() : window.reality.connect(state.value!.prefs.mode)) }
async function importProfile() { await run(async () => { const s = await window.reality.importProfile(uri.value); importing.value = false; uri.value = ''; return s }) }
async function settings() { draft.value = { ...state.value!.prefs }; page.value = 'settings'; await run(async () => { const [next, names] = await Promise.all([window.reality.startup(), window.reality.interfaces()]); interfaces.value = names; return next }) }
async function changeStartup(event: Event) {
  const input = event.target as HTMLInputElement
  await run(() => window.reality.setStartup(input.checked))
  input.checked = state.value!.startup.enabled
}
let unsubscribe = () => {}, timer: ReturnType<typeof setInterval>
onMounted(async () => { unsubscribe = window.reality.onState(receive); await run(async () => window.reality.initial()); timer = setInterval(() => now.value = Date.now(), 1000) })
onUnmounted(() => { unsubscribe(); clearInterval(timer) })
</script>

<template>
  <div class="app-shell">
    <header class="titlebar"><span class="brand"><Shield :size="20"/> REALITY <b>VPN</b></span><span class="title-note">PRIVATE BY DESIGN</span><div class="window-actions"><button aria-label="Свернуть" @click="window.reality.minimize()"><Minus :size="17"/></button><button aria-label="Закрыть" @click="window.reality.close()"><X :size="18"/></button></div></header>
    <aside><div class="workspace">ВАШЕ ПРОСТРАНСТВО</div><nav><button :class="{ active: page === 'home' }" @click="page = 'home'"><Shield :size="19"/> Подключение</button><button :class="{ active: page === 'profiles' }" @click="page = 'profiles'"><Globe2 :size="19"/> Мои серверы <span class="count">{{ state?.profiles.length || 0 }}</span></button><button :class="{ active: page === 'settings' }" @click="settings"><SlidersHorizontal :size="19"/> Настройки</button></nav><div class="sidebar-bottom"><div class="core-badge"><Radio :size="15"/> Xray · REALITY</div><p>Ваш трафик.<br>Ваши правила.</p><small>Reality VPN {{ state?.version }}</small></div></aside>
    <main v-if="state">
      <div v-if="error || connection?.error" class="error" role="alert">{{ error || connection?.error }}</div>
      <template v-if="page === 'home'">
        <div class="page-heading"><div><div class="eyebrow">БЕЗОПАСНЫЙ ИНТЕРНЕТ</div><h1>Свобода подключения<span>.</span></h1><p>Приватный доступ одним нажатием.</p></div><span class="protocol"><LockKeyhole :size="13"/> VLESS + REALITY</span></div>
        <section class="connection-card" :class="{ connected: online, degraded, busy: transitioning || verifying }">
          <div class="status" role="status"><LoaderCircle v-if="transitioning || verifying" class="spin" :size="13"/><TriangleAlert v-else-if="degraded" :size="13"/><span v-else class="status-dot"/>{{ label }}<span v-if="online && connection?.latency !== null" class="latency">{{ connection?.latency }} мс</span></div>
          <div class="power-orbit"><button class="power" :disabled="pending || (!idle && !connected) || !selected" :aria-label="connected ? 'Отключить' : 'Подключить'" @click="toggle"><LoaderCircle v-if="transitioning" class="spin" :size="46" :stroke-width="1.7"/><Power v-else :size="48" :stroke-width="1.7"/></button></div>
          <h2 :key="heading" class="status-heading">{{ heading }}</h2><p class="connection-description">{{ transitioning ? connection?.stage : connected ? `${connection?.mode === 'vpn' ? 'VPN / TUN' : 'Прокси'} · ${elapsed}` : 'Выберите режим и включите соединение' }}</p>
          <div v-if="degraded" class="health-warning"><span>{{ connection?.healthMessage }}</span><button :disabled="pending" @click="run(() => window.reality.recheck())"><RefreshCw :size="13"/> Проверить ещё раз</button></div>
          <div v-else-if="verifying" class="checking-note">Проверка HTTPS через сервер · до 5 секунд</div>
          <div class="mode-switch"><button :class="{ chosen: state.prefs.mode === 'proxy' }" :disabled="!idle || pending" @click="run(() => window.reality.savePrefs({ ...state!.prefs, mode: 'proxy' }))"><Globe2 :size="16"/> Прокси</button><button :class="{ chosen: state.prefs.mode === 'vpn' }" :disabled="!idle || pending" @click="run(() => window.reality.savePrefs({ ...state!.prefs, mode: 'vpn' }))"><Shield :size="16"/> VPN / TUN</button></div>
          <small class="mode-caption">{{ state.prefs.mode === 'vpn' ? 'IPv4 + IPv6 · требуются права администратора' : 'Для приложений, использующих системный прокси' }}</small>
        </section>
        <div class="lower-grid"><button class="server-card" @click="page = 'profiles'"><div class="server-symbol"><Globe2 :size="24"/></div><div><small>ТЕКУЩИЙ СЕРВЕР</small><strong>{{ selected?.name || 'Добавить сервер' }}</strong><span>{{ selected ? `${selected.host}:${selected.port}` : 'Импортируйте VLESS-ссылку' }}</span></div><ChevronRight :size="18"/></button><div class="traffic-panel"><div class="traffic-card" :class="{ stale: connected && connection?.statsStatus === 'stale' }"><div :class="{ flowing: connected && (connection?.downRate || 0) > 0 }"><ArrowDown :size="17"/><small>Получено</small><strong>{{ connection?.statsStatus === 'pending' && connected ? '—' : bytes(connection?.down) }}</strong><span class="traffic-rate">{{ connected && connection?.statsStatus === 'ready' ? bytes(connection?.downRate) + '/с' : '—' }}</span></div><div :class="{ flowing: connected && (connection?.upRate || 0) > 0 }"><ArrowUp :size="17"/><small>Отправлено</small><strong>{{ connection?.statsStatus === 'pending' && connected ? '—' : bytes(connection?.up) }}</strong><span class="traffic-rate">{{ connected && connection?.statsStatus === 'ready' ? bytes(connection?.upRate) + '/с' : '—' }}</span></div></div><div class="stats-note" :class="{ warning: connected && connection?.statsStatus === 'stale' }">{{ statsNote }}</div></div></div>
        <div class="routing-note"><Route :size="16"/><span>{{ state.prefs.ruDirect ? 'Российские сайты — напрямую' : 'Все внешние сайты — через сервер' }}</span><span class="dot-divider">·</span><span>Fingerprint: {{ selected?.fingerprint || 'firefox' }}</span></div>
      </template>
      <template v-else-if="page === 'profiles'">
        <div class="page-heading"><div><div class="eyebrow">ВАШИ МАРШРУТЫ</div><h1>Мои серверы<span>.</span></h1><p>Импортируйте ссылку из своей VPN-панели.</p></div><button class="primary" @click="importing = true"><Plus :size="17"/> Добавить</button></div>
        <div v-if="!state.profiles.length" class="empty"><Globe2 :size="52"/><h2>Начнём с сервера</h2><p>Нужна ссылка vless:// с REALITY и XTLS Vision.</p><button class="primary" @click="importing = true">Импортировать ссылку</button></div>
        <article v-for="profile in state.profiles" :key="profile.id" class="profile-card" :class="{ selected: profile.id === state.selected }"><div class="server-symbol"><Globe2 :size="25"/></div><div class="profile-info"><h3>{{ profile.name }}</h3><p>{{ profile.host }}:{{ profile.port }} · {{ profile.fingerprint }}</p><small>{{ profile.sni }}</small></div><button class="icon-button" title="Скопировать ссылку" @click="run(() => window.reality.copyAccess(profile.id))"><Copy :size="18"/></button><button class="icon-button" :disabled="!idle || pending" title="Удалить профиль" @click="run(() => window.reality.removeProfile(profile.id))"><Trash2 :size="18"/></button><button class="select-button" :disabled="!idle || pending" @click="run(() => window.reality.selectProfile(profile.id))"><Check v-if="profile.id === state.selected" :size="17"/>{{ profile.id === state.selected ? 'Выбран' : 'Выбрать' }}</button></article>
      </template>
      <template v-else-if="draft">
        <div class="page-heading"><div><div class="eyebrow">ПОД ВАШИМ КОНТРОЛЕМ</div><h1>Настройки<span>.</span></h1><p>Изменения применяются при следующем подключении.</p></div></div>
        <section class="startup-settings"><h3>Запуск приложения</h3><label class="toggle-row"><span><b>Запускать при входе в Windows</b><small>Открывать Reality VPN автоматически · применяется сразу</small></span><input :checked="state.startup.enabled" :disabled="pending || !state.startup.available" type="checkbox" role="switch" @change="changeStartup"/></label><p v-if="state.startup.disabledByWindows" class="startup-note">Автозапуск отключён в Windows. Включите переключатель, чтобы разрешить его снова.</p><p v-else-if="state.startup.portable" class="startup-note">Для portable оставьте EXE в постоянной папке. После перемещения файла или перехода на новый EXE включите автозапуск заново.</p></section>
        <form class="settings" @submit.prevent="run(() => window.reality.savePrefs(draft!))">
          <fieldset :disabled="!idle || pending"><h3>Маршрутизация</h3><label class="toggle-row"><span><b>Российские сайты напрямую</b><small>Домены РФ и российские IP обходят VPN</small></span><input v-model="draft.ruDirect" type="checkbox"/></label><label class="toggle-row"><span><b>Системный прокси</b><small>Автоматическая настройка и восстановление Windows</small></span><input v-model="draft.manageProxy" type="checkbox"/></label><label class="toggle-row"><span><b>Защита DNS в VPN / TUN</b><small>WFP блокирует DNS вне туннеля</small></span><input v-model="draft.strictDns" type="checkbox"/></label><label class="field-label">Исходящий интерфейс<select v-model="draft.interface"><option value="">Автоматически</option><option v-for="name in interfaces" :key="name">{{ name }}</option></select></label><div class="form-grid"><label class="field-label">SOCKS-порт<input v-model.number="draft.socksPort" type="number" min="1024" max="65535"/></label><label class="field-label">HTTP-порт<input v-model.number="draft.httpPort" type="number" min="1024" max="65535"/></label></div><div class="form-grid"><label class="field-label">Напрямую<textarea v-model="draft.directDomains" placeholder="example.ru" rows="3"/></label><label class="field-label">Через VPN<textarea v-model="draft.proxyDomains" placeholder="example.com" rows="3"/></label></div><small>По одному домену на строку. OpenAI и OpenCode всегда направляются через сервер.</small><div class="settings-footer"><span v-if="!idle">Отключитесь, чтобы изменить настройки</span><button class="primary" type="submit"><Check :size="17"/> Сохранить</button></div></fieldset>
        </form>
      </template>
      <footer><span><LockKeyhole :size="12"/> Профили зашифрованы в Windows</span><span>XTLS Vision · {{ state.version }}</span></footer>
    </main>
    <div v-if="importing" class="modal-backdrop" @click.self="importing = false"><form class="modal" @submit.prevent="importProfile"><button type="button" class="modal-close icon-button" aria-label="Закрыть" @click="importing = false"><X :size="20"/></button><div class="server-symbol"><Plus :size="25"/></div><h2>Новый маршрут</h2><p>Вставьте вашу VLESS REALITY ссылку.</p><textarea v-model="uri" autofocus placeholder="vless://…" rows="4" required spellcheck="false"/><div v-if="error" class="error">{{ error }}</div><div class="modal-actions"><button type="button" class="secondary" @click="run(async () => { uri = await window.reality.clipboard() })"><Clipboard :size="16"/> Вставить</button><button class="primary" :disabled="pending || !uri.trim()">Добавить сервер</button></div></form></div>
  </div>
</template>
